class Box<T> {
    private T value;

    Box(T value) {
        this.value = value;
    }

    public T getValue() {
        return this.value;
    }
}

public class Demo3 {
    public static void main(String[] args) {
        Box<Integer> b1 = new Box<>(10);
        Box<String> b2 = new Box<>("Hello");
        Box<Boolean> b3 = new Box<>(false);

        System.out.println(b1.getValue() + 5);
        System.out.println(b2.getValue());
        System.out.println(b3.getValue());
    }
}

public class Demo {
    public static void main(String[] args) {
        String s = "Hello";
        Object obj = s;            // upcasting

        Object obj2 = "Aditya";
        String s2 = (String) obj2; // downcasting
        System.out.println(s2);

        Object obj3 = 10;
        String s3 = (String) obj3;
        System.out.println(s3);
    }
}

class Animal {
    void display() { System.out.println("Displaying Animal"); }
}

interface Swimmable {
    void swim();
}

class Dog extends Animal { }

class Fish extends Animal implements Swimmable {
    public void swim() { System.out.println("Fish is swimming"); }
}

class Box<T extends Animal & Swimmable> {
    T value;

    void test() {
        value.display();   // Line C
        value.swim();      // Line D
    }
}

public class Demo7 {
    public static void main(String[] args) {
        Box<Fish> b1 = new Box<>();   // Line A
        Box<Dog> b2 = new Box<>();    // Line B
    }
}
